/* Dispute Studio: original, local-first credit case workspace. No external libraries. */
'use strict';
const STORE='dispute-studio-state-v1';
const dbName='dispute-studio-files-v1';
const BUREAUS=['Experian','Equifax','TransUnion'];
const LINKS={
  Experian:'https://www.experian.com/help/dispute-credit/',
  Equifax:'https://www.equifax.com/personal/credit-report-services/credit-dispute/',
  TransUnion:'https://www.transunion.com/credit-disputes/dispute-your-credit',
  reports:'https://www.annualcreditreport.com/',
  ftc:'https://www.identitytheft.gov/',
  cfpb:'https://www.consumerfinance.gov/consumer-tools/credit-reports-and-scores/answers/key-terms/credit-report-disputes/',
  fcra:'https://www.consumerfinance.gov/ask-cfpb/how-long-does-it-take-to-repair-an-error-on-a-credit-report-en-1339/',
  fdcp:'https://www.consumerfinance.gov/ask-cfpb/can-a-debt-collector-still-collect-a-debt-after-ive-disputed-it-en-338/',
  regulation:'https://www.consumerfinance.gov/rules-policy/regulations/1006/38/',
  complaint:'https://www.consumerfinance.gov/complaint/',
  breach:'https://haveibeenpwned.com/'
};
const TYPES=['Collection','Charge-off','Repossession','Late payments','Wrong detail','Not my account','Medical collection','Inquiry','Personal information','Public record','Other'];
const ISSUE_OPTS=[
 ['balance','Balance is incorrect','Payments, fees, settlement or other amount differs from records'],
 ['date','A date is wrong','First delinquency, opening, closing or payment date'],
 ['paid','Paid / settled, but shows unpaid','Account status is not updated'],
 ['duplicate','Possible duplicate reporting','More than one entry needs investigation'],
 ['late','Late mark is inaccurate','30/60/90-day payment history differs from records'],
 ['notmine','Account is not mine','Only choose if you know it is not yours'],
 ['inquiry','Inquiry is inaccurate','The inquiry entry needs investigation'],
 ['personal','Personal information is wrong','Name, address, phone or employer'],
 ['bankruptcy','Discharged account reported inaccurately','Balance or past-due status differs from records'],
 ['other','Another specific reporting error','Describe the precise inaccuracy']
];
const QUESTIONS=[['unrecognized','I do not recognize this collector or account'],['amount','The claimed amount needs an itemized explanation'],['ownership','The current creditor needs to be identified'],['notice','I have not received a validation notice']];
const RECORDS=['Account statements','Proof of payment','Validation notice','Creditor correspondence','Highlighted credit report','Settlement confirmation','Court or bankruptcy records','FTC identity theft report','Other supporting records'];
const LETTER_TYPES=[['bureau','Bureau dispute'],['collector','Debt validation'],['direct','Creditor dispute'],['goodwill','Goodwill request'],['identity','Identity theft'],['personal','Personal info'],['inquiry','Inquiry dispute']];
const NAV=[['home','⌂','Home'],['cases','◫','Cases'],['reader','▤','Reader'],['letters','✎','Letters'],['evidence','▧','Evidence'],['learn','◈','Learn'],['advanced','✦','Deep Desk']];
const MAIN_TABS=new Set(['home','cases','reader','letters','advanced']);
const TODAY=()=>new Date().toLocaleDateString('en-CA');
const ID=()=> 'd'+Math.random().toString(36).slice(2,11)+Date.now().toString(36);
const E=s=>String(s??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const money=v=>Number.isFinite(Number(v))&&v!==''?'$'+Number(v).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2}):'';
const displayDate=v=>{if(!v)return '';const [y,m,d]=v.split('-').map(Number);return new Date(y,m-1,d).toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'});};
const addDays=(v,n)=>{if(!v)return '';const d=new Date(v+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const daysUntil=v=>v?Math.ceil((new Date(v+'T12:00:00')-new Date())/864e5):null;
const fileSize=n=>n>=1048576?(n/1048576).toFixed(1)+' MB':Math.ceil(n/1024)+' KB';
const fmt=(s,missing='[fill in]')=>String(s??'').trim()||missing;
const arr=(v)=>Array.isArray(v)?v:[];
const demoClient=()=>{const c=newClient('Alex Morgan');Object.assign(c,{address:'123 Example Street',city:'Brooklyn',state:'NY',zip:'11201',isClient:false});const t=c.items[0];Object.assign(t,{type:'Collection',collector:'Harlow Recovery Services',originalCreditor:'First Lakeshore Card',account:'4471',balance:'842',correctBalance:'615',why:'Payments totaling $227 from 2024 were not credited.',ownership:'yes',issues:['balance'],questions:['amount'],records:['Account statements','Proof of payment','Validation notice'],reportDate:TODAY(),validationNotice:'2026-11-12',validationEnd:'2026-12-12',firstMissed:'2023-06-03',bureaus:['Experian','Equifax','TransUnion']});return c;};
function newItem(){return {id:ID(),type:'Collection',collector:'',originalCreditor:'',account:'',balance:'',correctBalance:'',status:'',why:'',otherDetails:'',dateExplanation:'',firstMissed:'',firstLate:'',lastPayment:'',statusDate:'',reportDate:'',firstReported:'',validationNotice:'',validationEnd:'',ownership:'unsure',priorDispute:'none',courtPapers:false,identityConfirmed:false,issues:[],questions:[],records:[],bureaus:[...BUREAUS],letterAddresses:{},recipientName:'',notes:'',sentDates:{},bureauReports:{},bureauDisputes:{},responses:{},reviewed:{},delivery:'online',files:[],createdAt:new Date().toISOString()};}
function newClient(name=''){const item=newItem();return{id:ID(),name,address:'',city:'',state:'',zip:'',email:'',phone:'',isClient:false,authorization:false,items:[item],activeItemId:item.id,createdAt:new Date().toISOString()};}
function initialState(){const empty={tab:'home',step:'profile',letter:'bureau',bureau:'Experian',saving:false,clients:[],activeId:null};try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved&&saved.saving&&Array.isArray(saved.clients))return{...empty,...saved,tab:'home',step:'profile',letter:'bureau',bureau:'Experian',saving:true};}catch(_e){}return empty;}
let state=initialState();
let signature=null; // Intentionally never persisted or copied to case codes.
let tempFiles=new Map();let objectURLs=new Map();let toastTimer;
function activeClient(){return state.clients.find(c=>c.id===state.activeId)||null}
function activeItem(){const c=activeClient();return c?.items?.find(i=>i.id===c.activeItemId)||c?.items?.[0]||null}
function persist(){if(state.saving){try{localStorage.setItem(STORE,JSON.stringify({...state,tab:'home',step:'profile',letter:'bureau',bureau:'Experian'}))}catch(e){toast('Local storage is full. Export a backup.')}}}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2800)}
function go(tab){state.tab=tab;render();window.scrollTo({top:0,behavior:'instant'})}
function iconText(t){return t||'◈'}
function initials(name){return (name||'New').trim().split(/\s+/).slice(0,2).map(s=>s[0]?.toUpperCase()||'').join('')}
function tabName(){return NAV.find(n=>n[0]===state.tab)?.[2]||'Home'}
function clientLabel(c){return c?.name?.trim()||'Untitled client'}
function itemLabel(i){return i?.collector||i?.originalCreditor||i?.type||'New entry'}
function shell(page){const active=activeClient();return `<div class="app-layout"><aside class="desktop-nav"><div class="brand"><div class="brand-mark">DS<span class="mark-dot">✦</span></div><div><div class="brand-title">Dispute Studio <span class="fusion-tag">9.0</span></div><div class="brand-sub">CASE WORKSPACE</div></div></div>${NAV.map(n=>`<button data-action="nav" data-value="${n[0]}" class="${state.tab===n[0]?'active':''}"><span class="nav-symbol">${n[1]}</span>${n[2]}</button>`).join('')}<div class="sidebar-foot">Made for your iPhone. Runs locally.<div>${state.saving?'Device saving enabled':'Saving is off'}</div></div></aside><div class="main-layout"><header class="app-header"><div class="brand"><div class="brand-mark">DS<span class="mark-dot">✦</span></div><div><div class="brand-title">Dispute Studio <span class="fusion-tag">9.0</span></div><div class="brand-sub">${active?E(clientLabel(active)):'YOUR PRIVATE WORKSPACE'}</div></div></div><div class="header-actions"><button class="storage-pill" data-action="toggle-save" title="Toggle local saving"><span class="dot ${state.saving?'':'off'}"></span>${state.saving?'Saving on':'Save off'}</button><button class="icon-btn" title="Settings and backup" aria-label="Settings and backup" data-action="settings">⚙</button></div></header><main>${page}<div class="footer-note">Dispute Studio 9 • Free knowledge backup + optional AI • No automatic disputes or submissions<br>Information only, not a legal service.</div></main></div></div><nav class="bottom-nav" aria-label="Main navigation">${NAV.filter(n=>MAIN_TABS.has(n[0])).map(n=>`<button class="nav-btn ${state.tab===n[0]?'active':''}" data-action="nav" data-value="${n[0]}"><span class="nav-symbol">${n[1]}</span><span>${n[2]}</span></button>`).join('')}</nav>`;}
function empty(title,desc,action='add-client',label='Create a case',emoji='✧'){return `<div class="card empty"><span class="emoji">${emoji}</span><h3>${E(title)}</h3><p>${E(desc)}</p><button class="btn primary" data-action="${action}">${E(label)}</button></div>`}
function metric(n,label,sub=''){return `<div class="card metric flat"><strong class="mono">${n}</strong><span>${label}</span>${sub?`<br><small>${E(sub)}</small>`:''}</div>`}
function checklist(c,i){return [
  ['Create a client profile',!!c],['Record the reporting entry',!!(i&&(i.collector||i.originalCreditor||i.type)&&i.account)],['Identify a specific error',!!i?.issues?.length],['Attach actual supporting records',!!i?.files?.length],['Review and sign a letter',!!i&&Object.values(i.reviewed||{}).some(Boolean)],['Record when the dispute was submitted',!!i&&Object.values(i.sentDates||{}).some(Boolean)]
]}
function homePage(){const c=activeClient(),i=activeItem();const allItems=state.clients.reduce((sum,x)=>sum+arr(x.items).length,0);const allFiles=state.clients.reduce((n,x)=>n+x.items.reduce((m,y)=>m+arr(y.files).length,0),0);const steps=checklist(c,i);const percent=Math.round(100*steps.filter(x=>x[1]).length/steps.length);return `<section class="hero"><div><div class="eyebrow">SMART REPORTS + DEEP DISPUTE WORKFLOW</div><h1>From screenshot.<br>To a verified case.</h1><p>Scan credit report pages, hear an explanation, compare all three bureaus, then autofill accurate drafts. Review each claim, sign, and track the response.</p></div><div class="row-wrap"><button class="btn mint" data-action="nav" data-value="reader">▤ Scan a credit report</button><button class="btn ghost" data-action="add-client">＋ New client</button></div></section><div class="grid-3" style="margin-top:14px">${metric(state.clients.length,'Clients')}${metric(allItems,'Credit items')}${metric(allFiles,'Evidence files')}</div>${!state.saving?`<div class="callout warning top-banner"><strong>Saving is off.</strong> Refreshing closes this session. Turn on device saving from the top-right before entering personal details if you want them available later. Files can be temporary until you opt in. Local storage is not encrypted.</div>`:''}<div class="section-title"><h3>Pick up where you left off</h3>${c?'<span class="pill success">Active case</span>':''}</div>${c?`<div class="card"><div class="row-between"><div class="row"><div class="avatar">${E(initials(c.name))}</div><div><strong>${E(clientLabel(c))}</strong><div class="muted small">${arr(c.items).length} credit item(s) • ${E(itemLabel(i))}</div></div></div><button class="btn secondary sm" data-action="nav" data-value="cases">Open →</button></div><div class="spacer-15"></div><div class="row-between"><small class="muted">Case preparation</small><strong class="small">${percent}%</strong></div><div style="height:7px;background:#293952;border-radius:10px;overflow:hidden;margin:8px 0 14px"><div style="width:${percent}%;height:100%;background:linear-gradient(90deg,#8a98fc,#64e6c9);border-radius:10px"></div></div><div class="grid-2">${steps.map(x=>`<div class="inline-status ${x[1]?'done':''}"><span class="circle">${x[1]?'✓':'○'}</span><span>${x[0]}</span></div>`).join('')}</div><div class="spacer-8"></div><div class="row-wrap"><button class="btn primary" data-action="nav" data-value="letters">Open letter studio</button><button class="btn secondary" data-action="nav" data-value="reader">▤ Read credit report</button></div></div>`:empty('Your workspace is ready','Create a case or explore a prefilled example. No account or subscription required.','demo','Load example case','✦')}
<div class="fusion-panel"><div class="fusion-panel-icon">✦</div><div class="fusion-panel-content"><span class="fusion-panel-kicker">ADVANCED TOOLS • PRESERVED FROM YOUR ORIGINAL APP</span><h3>Deep Dispute Desk</h3><p>Creditor directory, validation clocks, more letter routes, identity-theft steps, settlement requests and the original Desk 2 learning guides. The full original workflow is preserved.</p><button class="btn mint" data-action="nav" data-value="advanced">Explore advanced tools →</button></div></div><div class="section-title"><h3>Quick access</h3></div><div class="grid-2"><button class="case-item" data-action="nav" data-value="reader"><div class="avatar" style="background:#21665e">▤</div><div class="grow"><strong>Read & analyze</strong><small>Scan, explain, compare & autofill</small></div></button><button class="case-item" data-action="nav" data-value="letters"><div class="avatar" style="background:#35427e">✎</div><div class="grow"><strong>Letter Studio</strong><small>Auto-fill, sign, PDF</small></div></button><button class="case-item" data-action="nav" data-value="evidence"><div class="avatar" style="background:#24645e">▧</div><div class="grow"><strong>Evidence Vault</strong><small>No file-count limit</small></div></button><button class="case-item" data-action="nav" data-value="learn"><div class="avatar" style="background:#7b533f">◈</div><div class="grow"><strong>Learning Hub</strong><small>FCRA, FDCPA & steps</small></div></button><button class="case-item" data-action="settings"><div class="avatar" style="background:#394f70">⇩</div><div class="grow"><strong>Backups & Transfer</strong><small>Export / import safely</small></div></button></div>`}
function field(label,scope,key,value,placeholder='',hint='',type='text',span=''){return `<div class="field ${span}"><label for="f-${scope}-${key}">${label}</label><input id="f-${scope}-${key}" autocomplete="off" type="${type}" data-scope="${scope}" data-field="${key}" value="${E(value)}" placeholder="${E(placeholder)}"/>${hint?`<div class="hint">${hint}</div>`:''}</div>`}
function area(label,scope,key,value,placeholder='',hint='',span='span-2'){return `<div class="field ${span}"><label for="f-${scope}-${key}">${label}</label><textarea id="f-${scope}-${key}" data-scope="${scope}" data-field="${key}" placeholder="${E(placeholder)}" rows="3">${E(value)}</textarea>${hint?`<div class="hint">${hint}</div>`:''}</div>`}
function selectField(label,scope,key,value,values,hint=''){return `<div class="field"><label>${label}</label><select data-scope="${scope}" data-field="${key}">${values.map(v=>{const opt=typeof v==='string'?[v,v]:v;return `<option value="${E(opt[0])}" ${opt[0]===value?'selected':''}>${E(opt[1])}</option>`}).join('')}</select>${hint?`<div class="hint">${hint}</div>`:''}</div>`}
function toggle(label,scope,key,value,hint=''){return `<label class="toggle-line"><input type="checkbox" data-scope="${scope}" data-field="${key}" ${value?'checked':''}/><span><strong>${label}</strong>${hint?`<span class="muted small">${hint}</span>`:''}</span></label>`}
function topCaseSelector(){const c=activeClient();return `<div class="row-wrap" style="margin-bottom:14px"><div class="field" style="flex:1;min-width:180px"><label>Current profile</label><select data-action="select-client">${state.clients.map(x=>`<option value="${x.id}" ${x.id===state.activeId?'selected':''}>${E(clientLabel(x))}</option>`).join('')}</select></div><button class="btn secondary" data-action="add-client" style="align-self:end">＋ Client</button></div>${c?`<div class="account-strip">${c.items.map(x=>`<button class="account-chip ${x.id===c.activeItemId?'selected':''}" data-action="select-item" data-id="${x.id}"><strong>${E(itemLabel(x))}</strong><small>${E(x.account?'•••• '+x.account:'Add report details')}</small></button>`).join('')}<button class="account-chip" style="min-width:95px;display:grid;place-items:center;border-style:dashed" data-action="add-item"><strong>＋ Item</strong><small>New account</small></button></div>`:''}`;}
function casesPage(){const c=activeClient(),i=activeItem();return `<div class="page-head"><div><div class="eyebrow">CASE MANAGER</div><h1>Clients & cases</h1><p>Separate profiles, multiple reporting items, one clear process.</p></div></div>${state.clients.length?topCaseSelector():empty('No profiles yet','Add a client or make a case for yourself. Every new profile starts with a blank credit item.')} ${c&&i?`<div class="steps" role="tablist" aria-label="Case sections">${[['profile','01 Profile'],['account','02 Report details'],['issues','03 What’s wrong'],['timeline','04 Dates & progress']].map(v=>`<button class="step-btn ${state.step===v[0]?'selected':''}" data-action="case-step" data-value="${v[0]}">${v[1]}</button>`).join('')}</div><div class="spacer-8"></div>${caseSection(c,i)}<div class="row-wrap" style="margin-top:17px"><button class="btn primary" data-action="nav" data-value="letters">Generate letters →</button><button class="btn secondary" data-action="nav" data-value="reader">Analyze report</button><button class="btn secondary" data-action="nav" data-value="evidence">Evidence files</button><button class="btn fusion-cta" data-action="advanced-with-item">✦ Open in Deep Desk</button><button class="btn ghost" data-action="delete-item">Delete item</button></div>`:''}`;}
function caseSection(c,i){if(state.step==='profile')return `<div class="card"><div class="section-title" style="margin:0 0 17px"><h3>Who owns the report?</h3><span class="pill">Auto-fills letters</span></div><div class="field-grid">${field('Full legal name','client','name',c.name,'As printed on report')}${field('Email (optional)','client','email',c.email,'For your records')}${field('Street address','client','address',c.address,'Street and apartment')}${field('City','client','city',c.city,'Brooklyn')}${field('State','client','state',c.state,'NY')}${field('ZIP code','client','zip',c.zip,'11201')}${field('Phone (optional)','client','phone',c.phone,'')}
<div class="field span-2">${toggle('This case belongs to someone else','client','isClient',c.isClient,'Use a separate profile for every person. They must review and sign their own statements.')}${c.isClient?toggle('Consumer authorized me to prepare this draft','client','authorization',c.authorization,'This is your record of authorization, not a substitute for required legal agreements.'):''}</div></div><div class="callout top-banner">The name and address here flow into every letter. For privacy, do not store Social Security numbers, full account numbers, passwords or one-time codes.</div></div>`;
if(state.step==='account')return `<div class="card"><h3 style="margin-bottom:6px">Copy the entry as shown</h3><p class="muted small">Use the details from the report, validation notice or statement. Leave unknown fields blank.</p><div class="field-grid">${selectField('Reporting item type','item','type',i.type,TYPES)}${field('Collector / reporting company','item','collector',i.collector,'Company name')}${field('Original creditor','item','originalCreditor',i.originalCreditor,'If different')}${field('Account reference (last 4 ONLY)','item','account',i.account,'4471','Never record a full account number.')}${field('Balance shown on report','item','balance',i.balance,'842.00','','number')}${field('Amount your records show','item','correctBalance',i.correctBalance,'615.00','','number')}${field('Status shown','item','status',i.status,'Collection / Open / Paid / Closed')}${field('Report date','item','reportDate',i.reportDate,'','','date')}${field('First date of missed payment','item','firstMissed',i.firstMissed,'','','date')}${field('First late mark (if known)','item','firstLate',i.firstLate,'','','date')}${field('Last payment date','item','lastPayment',i.lastPayment,'','','date')}${field('Date of reported status','item','statusDate',i.statusDate,'','','date')}${field('First appeared on report','item','firstReported',i.firstReported,'','','date')}${area('Notes from the credit report','item','notes',i.notes,'Paste a short factual transcription. No full identifiers.')}</div>${bureauReportCard(i)}</div>`;
if(state.step==='issues')return `<div class="card"><h3>Is this account yours?</h3><p class="muted small">Choose the truthful answer. A legitimate account can still contain an inaccurate field.</p><div class="choice-grid">${[['yes','Yes, it is mine','I know this account'],['unsure','Not sure yet','I need more information'],['no','No, not mine','I know it is not mine']].map(x=>`<button class="choice ${i.ownership===x[0]?'selected':''}" data-action="ownership" data-value="${x[0]}">${x[1]}<small>${x[2]}</small></button>`).join('')}</div><div class="line"></div><h3>What specifically needs correction?</h3><p class="muted small">Select only issues supported by the person's own records. Every selected error feeds the letter.</p><div class="checkboxes">${ISSUE_OPTS.map(x=>`<label class="toggle-line"><input type="checkbox" data-array="issues" data-value="${x[0]}" ${i.issues.includes(x[0])?'checked':''}/><span><strong>${x[1]}</strong><span class="muted small">${x[2]}</span></span></label>`).join('')}</div><div class="spacer-15"></div><div class="field-grid">${area('Explain what is inaccurate and why','item','why',i.why,'Example: My statement shows $615 after a $227 payment, but the report shows $842.','Give specific facts and document dates if available.')}${area('Correct date / duplicate entries / other details','item','dateExplanation',i.dateExplanation,'Specify the dates, names and records that support your dispute.')}</div><div class="line"></div><h3>Questions for a debt collector</h3><p class="muted small">A request to validate a debt is separate from an accuracy dispute with a bureau.</p><div class="checkboxes">${QUESTIONS.map(x=>`<label class="toggle-line"><input type="checkbox" data-array="questions" data-value="${x[0]}" ${i.questions.includes(x[0])?'checked':''}/><span>${x[1]}</span></label>`).join('')}</div><div class="line"></div><h3>Evidence you really have</h3><div class="checkboxes">${RECORDS.map(x=>`<label class="toggle-line"><input type="checkbox" data-array="records" data-value="${E(x)}" ${i.records.includes(x)?'checked':''}/><span>${E(x)}</span></label>`).join('')}</div><div class="line"></div><h3>Appears on which reports?</h3><div class="mini-flex">${BUREAUS.map(b=>`<button class="choice ${i.bureaus.includes(b)?'selected':''}" style="min-height:45px;flex:1;justify-content:center" data-action="bureau-toggle" data-value="${b}">${b}</button>`).join('')}</div>${i.ownership==='no'&&!i.issues.includes('notmine')?'<div class="callout top-banner">If you know an account is not yours, you may select “Account is not mine” as the inaccuracy.</div>':''}</div>`;
return `<div class="card"><h3>Timeline & delivery</h3><p class="muted small">Record what happened; due dates here are reminders, not authoritative court deadlines.</p><div class="field-grid">${field('Validation notice received','item','validationNotice',i.validationNotice,'','','date')}${field('Validation dispute-by date on notice','item','validationEnd',i.validationEnd,'','','date')}${selectField('Previous dispute?','item','priorDispute',i.priorDispute,[['none','No prior dispute'],['bureau','Yes, with a bureau'],['collector','Yes, with a collector'],['direct','Yes, with the creditor']])}</div><div class="spacer-15"></div>${toggle('Court papers were served','item','courtPapers',i.courtPapers,'Credit disputes do not pause lawsuits or court deadlines.')}${i.courtPapers?'<div class="callout warning top-banner"><strong>Urgent:</strong> Respond to the summons by the court’s deadline. A dispute letter does not replace a court response. Consult qualified local legal help.</div>':''}${i.validationEnd?`<div class="date-alert" style="margin-top:12px">Validation period date shown on your notice: <strong>${displayDate(i.validationEnd)}</strong> (${daysUntil(i.validationEnd)>=0?daysUntil(i.validationEnd)+' days remaining':'date has passed'}). This is the date entered by you, not a legal determination.</div>`:''}<div class="line"></div><h3>Track correspondence</h3><p class="muted small">Log the date the bureau received your dispute (not just when you mailed it).</p><div class="field-grid">${BUREAUS.map(b=>`<div class="field"><label>${b} — received date</label><input type="date" data-date-key="${b}" value="${E(i.sentDates?.[b]||'')}"/></div>`).join('')}${field('Collector received date','sent','Collector',i.sentDates?.Collector||'','','date')}</div><div class="line"></div><h3>Record bureau replies</h3><p class="small muted">Mark an outcome only after you read the actual response. Keep reply documents in Evidence; do not claim a deletion or correction until confirmed.</p><div class="response-grid">${BUREAUS.map(b=>{
 const rsp=i.responses?.[b]||{};return `<div class="response-card"><strong>${b}</strong><div class="field"><label>Response received date</label><input type="date" data-response-bureau="${b}" data-response-key="date" value="${E(rsp.date||'')}"></div><div class="field"><label>What did the letter say?</label><select data-response-bureau="${b}" data-response-key="status">${[['','Awaiting response'],['corrected','Corrected'],['deleted','Deleted'],['verified','Verified as reported'],['partial','Partially corrected'],['follow-up','Needs follow-up']].map(([v,l])=>`<option value="${v}" ${rsp.status===v?'selected':''}>${l}</option>`).join('')}</select></div><div class="field"><label>Response notes</label><textarea data-response-bureau="${b}" data-response-key="note" placeholder="Describe the exact response and any open questions">${E(rsp.note||'')}</textarea></div></div>`}).join('')}</div>
${BUREAUS.filter(b=>i.sentDates?.[b]).map(b=>`<div class="inline-status"><span class="circle">◷</span><span>${b}: estimated 30-day investigation mark <strong>${displayDate(addDays(i.sentDates[b],30))}</strong> (some cases may take longer)</span></div>`).join('')}</div>`;}
function bureauReportCard(item){
 const reports=item.bureauReports||{};
 if(!Object.keys(reports).some(b=>BUREAUS.includes(b)))return `<div class="callout top-banner">Upload a credit report in Reader to build a three-bureau comparison. If only one bureau has data, the others are marked not identified.</div>`;
 return `<div class="section-title"><h3>Three-bureau source details</h3><span class="pill">From reviewed reports</span></div><div class="matrix-grid case-matrix">${BUREAUS.map(b=>{const r=reports[b];return `<div class="matrix-cell"><b>${b}</b>${r?`<strong>${money(r.balance||'')}</strong><span>${E(r.status||'Status unknown')}</span><small>Last reported: ${E(r.lastReported||'Not shown')}</small><small>Account: •••• ${E(r.account||'Not shown')}</small>`:'<small>Not in the uploaded report set</small>'}</div>`}).join('')}</div><p class="small-print">These are source transcriptions, not proven errors. Letter Studio selects the details for the recipient bureau.</p>`;
}
function describeIssues(i,bureauFact=null){const lines=[];const detail=i.why?.trim();const extra=i.dateExplanation?.trim();
if(i.issues.includes('balance'))lines.push(`The reported balance${(bureauFact?.balance??i.balance)!==''?' of '+money(bureauFact?.balance??i.balance):''} appears inaccurate${i.correctBalance!==''?'; my records show '+money(i.correctBalance):''}.${detail?' '+detail:''}`);
if(i.issues.includes('date'))lines.push(`One or more reporting dates appear inaccurate.${extra?' According to my records, '+extra:''}`);
if(i.issues.includes('paid'))lines.push(`This account is reported as unpaid despite my records indicating a payment or settlement.${detail?' '+detail:''}`);
if(i.issues.includes('duplicate'))lines.push(`The same debt may be reported more than once. Please investigate whether each entry is accurate and identifies a separate reporting obligation.${extra?' Relevant details: '+extra:''}`);
if(i.issues.includes('late'))lines.push(`The reported late-payment history appears inaccurate.${extra?' According to my records, '+extra:''}`);
if(i.issues.includes('notmine'))lines.push(i.ownership==='no'?'This account is not mine. Please investigate whether it belongs to another consumer.':'I do not recognize this account and request investigation of its attribution to me.');
if(i.issues.includes('inquiry'))lines.push(`I dispute the accuracy of the inquiry entry and request an investigation into whether it is correctly attributed to me.${extra?' '+extra:''}`);
if(i.issues.includes('personal'))lines.push(`The personal information associated with this report is inaccurate.${extra?' Correct information: '+extra:''}`);
if(i.issues.includes('bankruptcy'))lines.push(`The balance or payment status associated with a bankruptcy discharge appears inaccurate.${extra?' My records show: '+extra:''}`);
if(i.issues.includes('other'))lines.push(`I dispute the following specific information: ${fmt(extra||detail,'[[describe the exact error]]')}.`);
return lines;}
function letterKey(){return state.letter+'|'+(state.letter==='bureau'?state.bureau:'general')}
function bureauDisputeEditor(item,bureau){
 const snap=item.bureauReports?.[bureau];const multi=Object.keys(item.bureauReports||{}).length>1;
 if(!multi)return '';
 const d=item.bureauDisputes?.[bureau]||{issues:[],why:'',correctBalance:''};
 return `<div class="card bureau-issues"><div class="row-between"><h3>Confirm ${bureau}-specific inaccuracies</h3><span class="pill warn">Required</span></div><p class="small soft">Different bureaus can report different information without either being wrong. <strong>Select only errors supported by documents for ${bureau}.</strong> Other bureaus do not inherit these allegations.</p>${snap?`<p class="small">The ${bureau} entry currently shows <strong>${E(money(snap.balance||''))}</strong> · ${E(snap.status||'Unknown status')} · reported ${E(snap.lastReported||'date not shown')}</p>`:''}<div class="checkboxes">${ISSUE_OPTS.map(o=>`<label class="toggle-line"><input type="checkbox" data-bureau-issue="${bureau}" data-bureau-issue-key="${o[0]}" ${(d.issues||[]).includes(o[0])?'checked':''}/><span>${E(o[1])}</span></label>`).join('')}</div><div class="field" style="margin-top:12px"><label>What exactly is inaccurate on ${bureau} and what records prove it?</label><textarea data-bureau-explain="${bureau}" rows="3" placeholder="My dated statement shows the correct amount, but this bureau displays an incorrect amount.">${E(d.why||'')}</textarea></div><div class="field"><label>Correct amount, if verified (optional)</label><input data-bureau-correct="${bureau}" value="${E(d.correctBalance||'')}" placeholder="0.00" inputmode="decimal"></div></div>`;
}
function buildLetter(c,i,type=state.letter,bureau=state.bureau){const bureauFact=i.bureauReports?.[bureau]||null;const multiBureau=type==='bureau'&&Object.keys(i.bureauReports||{}).length>1;const bd=type==='bureau'?i.bureauDisputes?.[bureau]:null;const scoped=bd?{...i,issues:bd.issues||[],why:bd.why||'',correctBalance:bd.correctBalance||'',dateExplanation:bd.why||''}:i;const issues=describeIssues(scoped,bureauFact);const errors=[];const delivery=i.delivery||'online';const addresses=i.letterAddresses||{};const addrKey=type==='bureau'?'bureau-'+bureau:type;const addr=addresses[addrKey]||'';const recipient= type==='bureau'?bureau:type==='collector'?i.collector:type==='direct'||type==='goodwill'?i.originalCreditor||i.collector:type==='personal'?bureau:type==='inquiry'?bureau:bureau;
const label= type==='bureau'?'Credit report accuracy dispute':type==='collector'?'Debt dispute and verification request':type==='direct'?'Direct dispute of furnished credit information':type==='goodwill'?'Goodwill adjustment request':type==='identity'?'Identity theft report and request to block fraudulent information':type==='personal'?'Personal information correction': 'Disputed inquiry';
if(!c.name?.trim())errors.push('Full legal name');if(!c.address?.trim()||!c.city?.trim()||!c.state?.trim()||!c.zip?.trim())errors.push('Complete mailing address');if(!i.collector?.trim()&&!i.originalCreditor?.trim()&&type!=='personal')errors.push('Reporting company / creditor');if(type==='collector'&&!i.collector?.trim())errors.push('Collector name');if(delivery==='mail'&&!addr.trim())errors.push('Recipient mailing address');if(c.isClient&&!c.authorization)errors.push('Client authorization acknowledgment');
if(['bureau','direct','personal','inquiry'].includes(type)&&issues.length===0)errors.push('Select a specific error');if(type==='collector'&&i.ownership==='yes'&&!i.questions?.length&&!issues.length)errors.push('Describe why you request verification');if(type==='identity'&&!i.identityConfirmed)errors.push('Confirm identity theft claim is truthful');if(type==='identity'&&!i.records.includes('FTC identity theft report'))errors.push('FTC identity theft report (if requesting a block)');
if(type==='bureau'&&!i.bureaus.includes(bureau))errors.push(`${bureau} not selected in the case`);if(multiBureau&&(!bd||!Array.isArray(bd.issues)||!bd.issues.length||String(bd.why||'').trim().length<12))errors.push(`Describe and select a record-supported inaccuracy specifically for ${bureau}; other bureaus do not inherit allegations`);if(i.issues.includes('notmine')&&i.ownership==='yes'&&type!=='goodwill')errors.push('Account ownership conflicts with the not-mine issue');if(type==='identity'&&i.ownership==='yes')errors.push('Identity theft claim conflicts with confirmed ownership');
const clientName=fmt(c.name,'[[full legal name]]');const senderAddress=fmt(c.address,'[[street address]]');const location=[c.city,c.state].filter(Boolean).join(', ')+' '+(c.zip||'');const accountId=(bureauFact?.account||i.account)?` ending ${bureauFact?.account||i.account}`:'';const accountName=bureauFact?.company||i.collector||i.originalCreditor||'the listed company';
const opener=`I am writing regarding ${accountName}${accountId} as shown on my consumer credit report${(bureauFact?.reportDate||i.reportDate)?' dated '+displayDate(bureauFact?.reportDate||i.reportDate):''}.`;
let body='';
if(type==='bureau')body=`I am disputing inaccurate or incomplete information in my credit file. ${opener}\n\nThe following specific information needs to be investigated:\n${issues.map((x,n)=>`${n+1}. ${x}`).join('\n')||'[[describe the specific inaccurate reporting]]'}\n\nPlease conduct a reasonable reinvestigation, review the supporting records I have provided, and correct or remove information that cannot be verified as accurate and complete. Please send the results and an updated copy of the relevant credit report when applicable.`;
if(type==='bureau'&&bureauFact){
 const shown=[bureauFact.balance!==''?'balance '+money(bureauFact.balance):'',bureauFact.status?'status '+bureauFact.status:'',bureauFact.lastReported?'updated '+displayDate(bureauFact.lastReported):''].filter(Boolean).join('; ');
 if(shown)body+='\n\nFor identification, the '+bureau+' report shows: '+shown+'. The factual inaccuracies I request you to investigate are specifically the items listed above.';
 }
if(type==='collector')body=`I am writing regarding your attempt to collect an alleged debt associated with ${accountName}${accountId}${i.balance?' in the amount of '+money(i.balance):''}. I dispute ${i.issues.includes('balance')?'the amount claimed':'this debt to the extent described below'} and request verification.\n\n${issues.length?issues.join('\n'):i.questions?.length?'I need additional information to understand the identity of the creditor, the basis for the balance, and the account to which it relates.':'I am requesting sufficient information to identify and verify the alleged obligation.'}\n\nPlease provide verification of the disputed debt and, if different from the current creditor, the name and address of the original creditor. Please explain the amount claimed, including payments, interest and fees as applicable.${i.validationEnd&&daysUntil(i.validationEnd)>=0?'\n\nTo the extent this written dispute is received within the validation period, please cease collection of the disputed amount until you provide the verification or a copy of a judgment required by 12 CFR § 1006.38(d)(2).':''}\n\nThis letter does not acknowledge liability or authorize a payment.`;
if(type==='direct')body=`I dispute the accuracy of information your organization furnished about ${accountName}${accountId}. ${opener}\n\nThe specific disputed information is:\n${issues.map((x,n)=>`${n+1}. ${x}`).join('\n')||'[[describe the specific inaccurate furnishing]]'}\n\nPlease investigate this direct dispute in accordance with applicable requirements, review the enclosed records, and correct any information that you determine is inaccurate or incomplete. Please send me the results in writing.`;
if(type==='goodwill')body=`I am writing to respectfully request a goodwill review of the reporting on ${accountName}${accountId}. I understand that accurate reporting is generally permitted and that you are not obligated to remove accurate history.\n\nI would appreciate consideration of a discretionary goodwill adjustment based on the circumstances below:\n\n${fmt(i.why,'[[Explain the circumstances truthfully, including what has changed and why you are asking]]')}\n\nI am not asking you to report anything false. Thank you for considering this request.`;
if(type==='identity')body=`I am reporting that the account or information associated with ${accountName}${accountId} resulted from identity theft and does not belong to me. I did not authorize the transactions or application associated with this item.\n\nI request that you block the identified identity-theft information from my consumer report as provided under applicable law, subject to the required documentation. I have included an identity theft report in the listed enclosures, and I can provide proof of identity through your official identity-verification process as required.\n\nPlease confirm the action taken and contact me in writing if additional documentation is needed. This report concerns only the specific item identified above.`;
if(type==='personal')body=`I am disputing inaccurate personal-identifying information in my credit file. The incorrect entry and correct information are:\n\n${fmt(i.dateExplanation||i.why,'[[Describe each incorrect name, address, phone or employer entry and the correct value]]')}\n\nPlease investigate the discrepancy and update or delete the inaccurate personal information as appropriate. I can provide supporting identity and address documentation through your official process.`;
if(type==='inquiry')body=`I am disputing the accuracy of an inquiry associated with ${accountName} on my credit report${(bureauFact?.reportDate||i.reportDate)?' dated '+displayDate(bureauFact?.reportDate||i.reportDate):''}.\n\n${fmt(i.dateExplanation||i.why,'[[Describe what is incorrect about this inquiry and any supporting evidence]]')}\n\nPlease investigate whether this entry is accurate and properly associated with my credit file, and correct or remove any inaccurate entry. Please provide the results of your investigation.`;
const recipients=[recipient||'[[recipient name]]'];if(delivery==='mail')recipients.push(addr.trim()||'[[recipient mailing address]]');
const sender=[clientName,senderAddress,fmt(location.trim(),'[[city, state ZIP]]')].join('\n');const enclosures=i.records?.length&&type!=='goodwill'?'\n\nEnclosures (copies): '+i.records.join('; '):'';
const text=[displayDate(TODAY()),'',sender,'',recipients.join('\n'),'',`Re: ${label}${accountId}`,'',body,'','Please respond in writing at the address listed above.','','Sincerely,','[[SIGNATURE]]',clientName].join('\n')+enclosures;if(/\[\[(?!SIGNATURE\]\])/.test(text))errors.push('Complete the highlighted letter blanks');
return {text,errors,recipient,label,addrKey,addr,delivery,type,bureau};}
function previewHtml(letter){const str=E(letter.text).replace(/\[\[(.*?)\]\]/g,(_m,x)=>x==='SIGNATURE'?(signature?`<img class="paper-sign" src="${signature}" alt="Handwritten signature"/>`:'<span style="display:inline-block;height:38px">&nbsp;</span>'):`<span class="missing">${E(x)}</span>`);return str;}
function packetList(c,i){const definitions=[...((i.collector||i.type==='Collection')?[['collector','Experian']]:[]),...BUREAUS.filter(b=>i.bureaus.includes(b)).map(b=>['bureau',b])];return definitions.map(([type,bureau])=>{const l=buildLetter(c,i,type,bureau);const key=type+'|'+(type==='bureau'?bureau:'general');return {...l,key,approved:!!i.reviewed?.[key],ready:!l.errors.length&&!!i.reviewed?.[key]};});}
function packetSection(c,i){const packet=packetList(c,i);const ready=packet.filter(p=>p.ready);return `<div class="section-title"><h3>4. Your dispute packet</h3><span class="pill ${ready.length===packet.length&&packet.length?'success':'warn'}">${ready.length} / ${packet.length} ready</span></div><div class="card flat"><p class="muted small">Each bureau needs its own fact-checked dispute. Validation requests are separate from bureau reinvestigations. Only confirmed letters are included in packet exports.</p><div class="stack">${packet.map(p=>`<button class="case-item" data-action="open-packet-letter" data-type="${p.type}" data-bureau="${p.bureau}"><div class="avatar" style="background:${p.ready?'#235449':'#3d3e65'}">${p.ready?'✓':'✎'}</div><div class="grow"><strong>${p.type==='collector'?'Collector validation':p.bureau+' dispute'}</strong><small>${p.ready?'Ready to export':p.errors.length?'Needs '+p.errors.length+' field(s)':'Review and confirm accuracy'}</small></div><span class="pill ${p.ready?'success':'warn'}">${p.ready?'Ready':'Draft'}</span></button>`).join('')}</div><div class="spacer-15"></div><div class="row-wrap"><button class="btn mint" data-action="pdf-packet" ${ready.length?'':'disabled'}>⬇ PDF packet (${ready.length})</button><button class="btn secondary" data-action="copy-packet" ${ready.length?'':'disabled'}>Copy ready letters</button></div><p class="small-print">The PDF packet combines ready letters in one file. Print each letter and send it to its own recipient separately.</p></div>`;}
function lettersPage(){const c=activeClient(),i=activeItem();if(!c||!i)return `<div class="page-head"><div><div class="eyebrow">LETTER STUDIO</div><h1>Letters that fill themselves.</h1><p>Select a profile first to generate a personalized draft.</p></div></div>${empty('Choose a client first','Every letter starts with verified client and credit item details.','add-client','Create client','✎')}`;
const l=buildLetter(c,i);const key=letterKey();const approved=!!i.reviewed?.[key];const ready=approved&&!l.errors.length;return `<div class="page-head"><div><div class="eyebrow">LETTER STUDIO</div><h1>Make it official.</h1><p>Your case information flows into the letter automatically.</p></div><button class="btn secondary sm" data-action="nav" data-value="cases">Edit profile</button></div>${topCaseSelector()}
<div class="section-title"><h3>1. Pick a letter</h3><span class="pill">7 templates</span></div><div class="letter-type">${LETTER_TYPES.map(t=>`<button class="step-btn ${state.letter===t[0]?'selected':''}" data-action="letter-type" data-value="${t[0]}">${t[1]}</button>`).join('')}</div>${['bureau','personal','inquiry','identity'].includes(state.letter)?`<div class="spacer-8"></div><div class="letter-toolbar">${BUREAUS.map(b=>`<button class="step-btn ${b===state.bureau?'selected':''}" data-action="bureau-select" data-value="${b}">${b}</button>`).join('')}</div>`:''}
<div class="section-title"><h3>2. Review & personalize</h3><span class="pill ${l.errors.length?'warn':'success'}">${l.errors.length?l.errors.length+' needs attention':'Fields complete'}</span></div>${state.letter==='bureau'?bureauDisputeEditor(i,state.bureau):''}<div class="two-panel"><div class="stack"><div class="card"><div class="field-grid">${selectField('How will this letter be used?','item','delivery',i.delivery||'online',[['online','Online portal / upload'],['mail','Printed & mailed']])}<div class="field"><label>Recipient</label><div class="bare-input">${E(l.recipient||'Missing reporting company')}</div></div>${area('Recipient address (for postal mail)','address',l.addrKey,l.addr,'Find the exact address on the current official bureau/collector page.','','span-2')}${area('Additional factual explanation','item','why',i.why,'Write only what your records support.','This is inserted into applicable templates.')}${state.letter==='identity'?toggle('I confirm this item resulted from identity theft','item','identityConfirmed',i.identityConfirmed,'Only confirm if this is true. You need the required identity-theft documentation.'):''}</div>${l.errors.length?`<div class="callout warning top-banner"><strong>Before exporting as ready:</strong><br>${l.errors.map(x=>'• '+E(x)).join('<br>')}</div>`:''}${state.letter==='goodwill'?'<div class="callout top-banner">Goodwill adjustments are discretionary. Accurate items are not automatically removable.</div>':''}<div class="spacer-15"></div><label class="toggle-line"><input type="checkbox" data-reviewed="${E(key)}" ${approved?'checked':''}/><span><strong>I reviewed the complete letter and every statement is true.</strong><span class="muted small">Required before treating it as ready. Editing the facts clears this confirmation.</span></span></label><div class="spacer-15"></div><div class="row-wrap"><button class="btn ${ready?'mint':'secondary'}" data-action="signature" ${ready?'':'disabled'}>✍ ${signature?'Change signature':'Sign with finger'}</button><button class="btn secondary" data-action="copy-letter" ${ready?'':'disabled'}>Copy letter</button></div></div>${state.letter==='bureau'?`<div class="card flat"><div class="row-between"><div><strong>Official submission</strong><div class="muted small">Submit it yourself; this app never logs in or sends anything.</div></div><span class="pill">${state.bureau}</span></div><div class="spacer-8"></div><a class="open-link external" href="${LINKS[state.bureau]}" target="_blank" rel="noopener noreferrer">Open ${state.bureau} dispute center <span>↗</span></a></div>`:''}</div><div class="stack"><div class="card" style="padding:13px"><div class="row-between" style="padding:4px 4px 12px"><div><strong>Live document</strong><div class="muted small">Changes appear here after typing.</div></div><span class="pill ${ready?'success':'warn'}">${ready?'Ready':'Draft'}</span></div><div class="paper" id="letterPreview">${previewHtml(l)}</div></div><div class="row-wrap"><button class="btn primary" style="flex:1" data-action="pdf-letter" ${ready?'':'disabled'}>⬇ Save / Share PDF</button><button class="btn secondary" data-action="print-letter" ${ready?'':'disabled'}>Print</button></div><div class="small-print">PDFs include the signature drawn during this session. If you haven’t signed, leave a blank line and sign by hand. iPhone can share the PDF to Files, AirDrop or Mail.</div></div></div>
<div class="section-title"><h3>3. Track delivery</h3></div><div class="card flat"><p class="muted small">Record the true delivery or receipt date. A prepared PDF does not mean a dispute was submitted.</p><div class="row-wrap"><button class="btn secondary" data-action="mark-sent">Mark received today</button><button class="btn ghost" data-action="nav" data-value="cases">View full timeline</button></div>${i.sentDates?.[state.letter==='bureau'?state.bureau:'Collector']?`<p class="small" style="color:var(--mint)">Recorded: ${displayDate(i.sentDates[state.letter==='bureau'?state.bureau:'Collector'])}</p>`:''}</div>${packetSection(c,i)}`;}
function evidencePage(){const c=activeClient(),i=activeItem();if(!c||!i)return `<div class="page-head"><div><div class="eyebrow">EVIDENCE VAULT</div><h1>Proof, organized.</h1><p>Keep screenshots, statements and receipts attached to the right case.</p></div></div>${empty('Create a case to add files','Attach screenshots to each credit item, with no artificial file-count limit.','add-client','New case','▧')}`;
const files=arr(i.files);return `<div class="page-head"><div><div class="eyebrow">EVIDENCE VAULT</div><h1>Receipts. Screenshots. Proof.</h1><p>Attach as many files as the device can store.</p></div></div>${topCaseSelector()}
<div class="dropzone" id="dropzone"><div style="font-size:30px;margin-bottom:5px">▧</div><strong>Add screenshots or PDFs</strong><p>Choose multiple files together. No app-imposed count limit.<br>Your device's available storage still applies.</p><label class="btn primary" for="filePicker">＋ Choose photos or files</label><input type="file" id="filePicker" accept="image/*,application/pdf" multiple/><div class="small-print" style="margin-top:10px">PNG • JPG • HEIC (browser support varies) • PDF</div></div>
<div class="callout top-banner"><strong>${state.saving?'Files stored on this device':'Temporary session files'}.</strong> ${state.saving?'Attachments are stored in this browser, unencrypted; they are not uploaded to a server. Export a full backup to avoid loss.':'Files remain in memory only while this page stays open. Turn on device saving to keep them after closing.'}</div>
<div class="section-title"><h3>Files for ${E(itemLabel(i))}</h3><span class="pill">${files.length} attached</span></div>${files.length?`<div class="stack">${files.map(x=>`<div class="document-card"><div class="doc-preview" id="thumb-${E(x.id)}">${x.type?.startsWith('image/')?'▧':'PDF'}</div><div class="grow"><strong>${E(x.name)}</strong><small>${fileSize(x.size||0)} • ${displayDate((x.createdAt||'').slice(0,10))}</small></div><button class="btn secondary sm" data-action="open-file" data-id="${E(x.id)}">View</button><button class="icon-btn" data-action="remove-file" data-id="${E(x.id)}" title="Delete attachment">×</button></div>`).join('')}</div>`:empty('No screenshots yet','Add highlighted report pages, payment receipts, notices and correspondence for this specific account.','choose-files','Choose evidence','▧')}
<div class="section-title"><h3>Evidence checklist</h3></div><div class="card flat"><div class="privacy-list">${['A copy of the credit report with the disputed entry marked','Records supporting the exact correction requested','Proof that you submitted and when the bureau or collector received it','Dispute results and the updated report'].map((x,n)=>`<div class="privacy-line"><span class="glyph">${n+1}.</span><span>${x}</span></div>`).join('')}</div><div class="callout warning top-banner">Send copies rather than originals. Bureau portals may request identity documents, but never enter full SSNs or passwords into this app.</div></div>`;}
function learnPage(){return `<div class="page-head"><div><div class="eyebrow">KNOWLEDGE BASE</div><h1>Learn the process.</h1><p>Verified official links and a straightforward, evidence-first workflow.</p></div></div><div class="card" style="background:linear-gradient(120deg,#2b386d,#1c5353)"><div class="eyebrow">WORKFLOW</div><h2 style="margin:7px 0">Pull → Review → Dispute → Track → Recheck</h2><p class="soft small">A credit dispute is for inaccurate or incomplete reporting. There are no guaranteed deletions, secret shortcuts or automatic submissions.</p><button class="btn mint" data-action="nav" data-value="cases">Start a case</button></div>
<div class="section-title"><h3>One-tap official portals</h3></div><div class="stack">${[['Free credit reports',LINKS.reports,'AnnualCreditReport.com'],...BUREAUS.map(b=>[b,LINKS[b],b+' online dispute center']),['Report identity theft',LINKS.ftc,'FTC IdentityTheft.gov']].map(x=>`<a class="open-link external" href="${x[1]}" rel="noopener noreferrer" target="_blank"><span><strong>${x[0]}</strong><br><small class="muted">${x[2]}</small></span><span>↗</span></a>`).join('')}</div>
<div class="section-title"><h3>Know your rights</h3></div><div class="course-grid"><div class="course-card"><details><summary>01 • What happens after a bureau dispute?</summary><p>Under the FCRA, a credit reporting agency generally has 30 days after receiving a dispute to investigate; certain situations allow up to 45 days. Keep the confirmation and actual receipt date. Review results and compare the updated information with your evidence.</p><a class="external small" href="${LINKS.fcra}" target="_blank" rel="noopener">Source: CFPB — investigation timelines</a></details></div><div class="course-card"><details><summary>02 • Collector debt validation</summary><p>If you dispute a debt in writing within the validation period, a covered debt collector generally must stop collection of the disputed portion until it provides verification or a copy of a judgment. A bureau dispute is a separate process. The exact rights depend on the collector and facts.</p><a class="external small" href="${LINKS.fdcp}" target="_blank" rel="noopener">Source: CFPB — debt validation</a></details></div><div class="course-card"><details><summary>03 • Exact errors beat blanket templates</summary><p>Name each inaccurate balance, date, status, late mark or identity detail. Attach supporting statements. An accurate negative record does not become removable just because a template demands it.</p><a class="external small" href="${LINKS.cfpb}" target="_blank" rel="noopener">Source: CFPB — disputes</a></details></div><div class="course-card"><details><summary>04 • Identity theft versus a data breach</summary><p>A company-wide breach does not by itself prove that a particular credit account was opened or used fraudulently. Verify the facts. If your identity was stolen, use the FTC recovery process and official bureau procedures; do not claim a false identity theft incident.</p><a class="external small" href="${LINKS.ftc}" target="_blank" rel="noopener">FTC recovery steps</a><div class="spacer-8"></div><a class="external small" href="${LINKS.breach}" target="_blank" rel="noopener">Optional breach exposure lookup</a></details></div><div class="course-card"><details><summary>05 • If a collector files a lawsuit</summary><p>A credit dispute letter does not stop a lawsuit or extend the response date on a summons. Preserve court documents, follow the actual court deadline and obtain qualified legal assistance where appropriate.</p></details></div><div class="course-card"><details><summary>07 • Put this app on your iPhone Home Screen</summary><p>Publish the included app files at an HTTPS website address using GitHub Pages or another static host. Open that website in Safari, tap the Share icon, choose Add to Home Screen, and enable Open as Web App if available. Download the ZIP and follow README.txt for step-by-step instructions.</p><p>Only the website code is public. Case data entered on the device is not published to the website; however, local device data and exported backups are not encrypted.</p></details></div><div class="course-card"><details><summary>06 • Goodwill requests and accurate records</summary><p>A goodwill letter asks for discretionary consideration, not a legal deletion. It should never assert that accurate information is fraudulent or inaccurate. Corrections are appropriate when specific reporting facts are wrong.</p></details></div></div>
<div class="section-title"><h3>Case tools</h3></div><div class="grid-2"><button class="case-item" data-action="settings"><div class="avatar">⇄</div><div class="grow"><strong>Case transfer</strong><small>Copy code and backups</small></div></button><button class="case-item" data-action="speak-help"><div class="avatar">◖</div><div class="grow"><strong>Read this aloud</strong><small>iPhone voice support</small></div></button></div><div class="callout warning top-banner"><strong>Professional-use note:</strong> A personal browser is not an encrypted client portal. If offering paid credit-repair services, use legally compliant agreements, authorization, privacy/security measures and applicable federal/state consumer protections. This app does not manage those requirements.</div>`;}
function settingsModal(){const c=activeClient();return `<div class="modal-head"><div><div class="eyebrow">CONTROL CENTER</div><h2>Settings & backups</h2></div><button class="icon-btn" data-action="close-modal" aria-label="Close">×</button></div><div class="settings-card"><div class="row-between"><div><h3>Keep cases on this device</h3><p>${state.saving?'Enabled: names, case details and evidence persist in this browser, unencrypted.':'Disabled: data is temporary and disappears when the page reloads.'}</p></div><button class="toggle-switch ${state.saving?'on':''}" data-action="toggle-save" aria-label="Turn local saving ${state.saving?'off':'on'}"></button></div></div><div class="settings-card"><h3>Backup this workspace</h3><p>Download a JSON backup. Full backup includes evidence images/PDFs; it may be large. Store it somewhere private and protected.</p><div class="row-wrap"><button class="btn primary" data-action="backup-full">Full backup + evidence</button><button class="btn secondary" data-action="backup-data">Cases only</button></div><div class="spacer-8"></div><label class="btn ghost block" for="backupImporter">Import a backup</label><input type="file" id="backupImporter" accept="application/json,.json" hidden/></div><div class="settings-card"><h3>Move a case by code</h3><p>Copy a current profile to another device. This <strong>unencrypted</strong> text contains personal information and case items; it excludes files, signatures and readiness confirmations.</p>${c?'<button class="btn secondary" data-action="copy-code">Copy current case code</button>':'<p>Add a client first.</p>'}<div class="spacer-8"></div><div class="field"><label>Paste a case code</label><textarea id="caseCodeInput" placeholder="Paste the code from another device" rows="3"></textarea></div><button class="btn secondary" data-action="load-code">Load copied case</button></div><div class="settings-card"><h3>Clear local data</h3><p>Delete all saved cases and local files. Export a backup first; this cannot be undone.</p><div class="row-wrap"><button class="btn danger sm" data-action="clear-all">Erase workspace</button>${c?'<button class="btn ghost sm" data-action="delete-client">Delete active client</button>':''}</div></div><p class="small-print" style="margin-top:14px">The app has no server, account login or cloud sync. Anyone with access to the unlocked browser or an exported backup could read the stored data. Do not enter SSNs, passwords, full account numbers or other highly sensitive data.</p>`;}
function openModal(content){const m=document.getElementById('modal');m.innerHTML=`<div class="modal-panel" role="dialog" aria-modal="true">${content}</div>`;m.hidden=false;}
function closeModal(){const m=document.getElementById('modal');m.hidden=true;m.innerHTML='';}
function newClientModal(){openModal(`<div class="modal-head"><div><div class="eyebrow">NEW CASE</div><h2>Whose credit report?</h2></div><button class="icon-btn" data-action="close-modal">×</button></div><p class="muted small">One profile per person. Start blank or copy over an example.</p><div class="field"><label for="newClientName">Full name (you can add it later)</label><input id="newClientName" placeholder="Enter name" autocomplete="off"></div><div class="spacer-15"></div><label class="toggle-line"><input type="checkbox" id="newIsClient"><span><strong>This belongs to a client / family member</strong><span class="muted small">A separate profile prevents mixing information.</span></span></label><div class="spacer-15"></div><button class="btn mint block" data-action="create-client">Create blank profile →</button>`);setTimeout(()=>document.getElementById('newClientName')?.focus(),70)}
function signatureModal(){openModal(`<div class="modal-head"><div><div class="eyebrow">FINGER SIGNATURE</div><h2>Sign this letter</h2></div><button class="icon-btn" data-action="close-modal">×</button></div><p class="muted small">The report owner should draw their own signature. It appears on PDFs from this session only and is never stored in a case or backup.</p><canvas class="sig-canvas" id="signaturePad" aria-label="Draw signature here"></canvas><p class="muted small">Tip: rotate your iPhone sideways for a wider signing area.</p><div class="row-wrap"><button class="btn secondary" data-action="clear-signature">Clear</button><button class="btn mint" style="flex:1" data-action="save-signature">Use this signature</button></div>`);initSignaturePad();}
let signedStrokes=0;
function initSignaturePad(){const canvas=document.getElementById('signaturePad');if(!canvas)return;const rect=canvas.getBoundingClientRect();const ratio=Math.min(window.devicePixelRatio||1,3);canvas.width=Math.round(rect.width*ratio);canvas.height=Math.round(rect.height*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);ctx.fillStyle='#fff';ctx.fillRect(0,0,rect.width,rect.height);ctx.lineCap='round';ctx.lineJoin='round';ctx.lineWidth=2.5;ctx.strokeStyle='#1a2234';let drawing=false; signedStrokes=0;
const pos=e=>{const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}};
canvas.addEventListener('pointerdown',e=>{e.preventDefault();canvas.setPointerCapture(e.pointerId);const p=pos(e);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x+.1,p.y+.1);ctx.stroke();drawing=true;signedStrokes++});canvas.addEventListener('pointermove',e=>{if(!drawing)return;e.preventDefault();const p=pos(e);ctx.lineTo(p.x,p.y);ctx.stroke()});for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>{drawing=false});}
function advancedPage(){const c=activeClient(),i=activeItem();return `<section class="page-head"><div><div class="eyebrow">DISPUTE DESK 2 × DISPUTE STUDIO</div><h1>Deep Dispute Desk</h1><p>The full detailed workflow from your uploaded Dispute Desk 2—restyled to match this app.</p></div></section>
<div class="fusion-banner"><div class="fusion-stars">✦ &nbsp; DEEP REVIEW</div><h2>Go further on every account.</h2><p>More fact checks, decision routes, completion safeguards, timelines and guidance—without removing the simpler Report Reader, multi-client manager or letter studio.</p><div class="row-wrap"><button class="btn mint" data-action="advanced-with-item" ${!c||!i?'disabled':''}>${c?'Send current credit item →':'Select a case first'}</button><button class="btn secondary" data-action="advanced-open-blank">Open Deep Desk</button></div><p class="fusion-fine">The Deep Desk keeps one case at a time and has its own device-saving control. Moving a client opens a separate review copy—changes return only when you choose to import them.</p></div>
<div class="section-title"><h3>Features from your Dispute Desk 2 ZIP</h3><span class="pill success">Original tools preserved</span></div>
<div class="fusion-feature-grid">
${[['◈','Detailed account questions','Collections, charge-offs, late payments, repossessions, medical debt, inquiries, personal details and public records.'],['⌛','Validation & reporting clocks','Notice dates, collection validation period, reporting-age checks and follow-up steps.'],['✉','Expanded letter routes','Bureau disputes, collector validation, direct disputes, goodwill, follow-ups, settlement terms and multi-letter packet review.'],['⌂','Creditor & collector directory','Company matching, mailing-address prompts and recipient address checking before a letter is marked ready.'],['◎','Identity theft & breaches','Identity-theft guidance, breach lookup references, lost-card guidance and source-linked educational tools.'],['▧','Evidence and signatures','Supporting documents, letter-specific sign-off, printable packets and copyable transfer codes.'],['◐','Light / dark appearance','A matching indigo, teal and dark-glass visual language; the full original controls stay available.'],['⇄','Move cases both ways','Send a selected item in; review and bring the advanced case back as a new Studio profile.']].map(x=>`<div class="fusion-feature"><span>${x[0]}</span><strong>${x[1]}</strong><p>${x[2]}</p></div>`).join('')}</div>
<div class="callout warning" style="margin-top:16px"><strong>Review before disputing.</strong> Report-reader suggestions are investigatory, not proof. Do not claim identity theft or a reporting mistake unless your facts and evidence support it. Letters are never submitted automatically.</div>
<div class="row-wrap" style="margin-top:15px"><button class="btn primary" data-action="nav" data-value="reader">▤ Read another report</button><button class="btn secondary" data-action="nav" data-value="learn">View learning hub</button></div>`}

async function fusionEnter(withItem){
  const c=activeClient(),i=activeItem();
  if(withItem&&(!c||!i)){toast('Select a client and item first');return;}
  if(state.clients.length&&!state.saving){
    const keep=confirm('Studio device saving is OFF. Leaving the page would lose unsaved clients and evidence. Turn ON local saving (unencrypted) before opening Deep Desk? Cancel to export a backup instead.');
    if(!keep)return;
    await setSave(true);
    try{if(!localStorage.getItem(STORE)){toast('This device could not save the Studio case. Export a backup first.');return;}}catch(_){toast('Device saving is unavailable. Export a backup first.');return;}
  }
  if(withItem){
    const ok=confirm('Open a review COPY of '+clientLabel(c)+' in Deep Desk? Deep Desk stores one case at a time. If you have unfinished work there, export its case code first. This will not change your Studio case.');
    if(!ok)return;
    try{sessionStorage.setItem('fusion:to-advanced',JSON.stringify({v:1,client:{name:c.name,address:c.address,city:c.city,state:c.state,zip:c.zip,isClient:c.isClient},item:structuredClone(i)}));}
    catch(e){toast('Could not prepare transfer in this browser. Use Open Deep Desk without autofill.');return;}
  }else{try{sessionStorage.removeItem('fusion:to-advanced');}catch(_){}}
  window.location.assign('./advanced-desk.html');
}
function fusionFromAdvanced(){
  let raw=null;try{raw=sessionStorage.getItem('fusion:from-advanced');sessionStorage.removeItem('fusion:from-advanced');}catch(_){return;}
  if(!raw)return;
  let o;try{o=JSON.parse(raw);if(o?.v!==1||!o.client||!Array.isArray(o.items)||o.items.length>40)throw Error('invalid');}catch(_){toast('Unable to read Advanced Desk transfer');return;}
  const ok=confirm('Advanced Desk sent '+o.items.length+' reviewed item(s) for '+(o.client.name||'this person')+'. Import as a NEW Studio profile? This keeps any existing profiles unchanged. You must check everything before using letters.');
  if(!ok)return;
  const c=newClient(String(o.client.name||'').slice(0,80));c.address=String(o.client.street||'').slice(0,180);c.city=String(o.client.city||'').slice(0,100);c.state=String(o.client.state||'').slice(0,30);c.zip=String(o.client.zip||'').slice(0,16);c.isClient=!!o.client.business;
  const typeBack={collection:'Collection',chargeoff:'Charge-off',repo:'Repossession',late:'Late payments',detail:'Wrong detail',notmine:'Not my account',medical:'Medical collection',inquiry:'Inquiry',personal:'Personal information',public:'Public record'};
  const factsBack={balance_wrong:'balance',dates_wrong:'date',paid_unpaid:'paid',duplicate:'duplicate',late_wrong:'late',status_wrong:'other',bankruptcy_incl:'bankruptcy',other_fact:'other'};
  c.items=o.items.map(a=>{const i=newItem();i.type=typeBack[a.type]||'Wrong detail';i.collector=String(a.furnisher||'').slice(0,130);i.originalCreditor=String(a.originalCreditor||'').slice(0,130);i.account=String(a.acct||'').replace(/\D/g,'').slice(-4);i.balance=String(a.reportedBalance||'').slice(0,30);i.correctBalance=String(a.correctBalance||'').slice(0,30);i.why=String(a.balanceWhy||'').slice(0,1800);i.status=String(a.statusText||'').slice(0,150);i.firstMissed=String(a.dofd||'');i.firstLate=String(a.firstLate||'');i.lastPayment=String(a.lastPayment||'');i.statusDate=String(a.statusDate||'');i.reportDate=String(a.reportDate||'');i.firstReported=String(a.reportedDate||'');i.validationNotice=String(a.noticeReceived||'');i.validationEnd=String(a.noticeDeadline||'');i.ownership=a.isMine==='no'?'no':a.isMine==='unsure'?'unsure':'yes';i.courtPapers=!!a.sued;i.priorDispute=a.prior||'none';i.bureaus=['Experian','Equifax','TransUnion'].filter(b=>a.bureaus?.[b.toLowerCase()]!==false);i.issues=Object.keys(a.facts||{}).filter(k=>a.facts[k]&&factsBack[k]).map(k=>factsBack[k]);i.notes=('From Deep Desk advanced review. Check all details.\n'+String(a.extra||'').slice(0,4500)).trim();i.reviewed={};return i;});
  if(!c.items.length)c.items=[newItem()];c.activeItemId=c.items[0].id;state.clients.push(c);state.activeId=c.id;state.step='account';signature=null;persist();go('cases');toast('Imported Advanced Desk items — confirm facts before signing');
}
function render(){document.getElementById('app').innerHTML=shell(state.tab==='home'?homePage():state.tab==='cases'?casesPage():state.tab==='letters'?lettersPage():state.tab==='evidence'?evidencePage():state.tab==='reader'?readerPage():state.tab==='advanced'?advancedPage():learnPage());if(state.tab==='evidence')loadThumbs();}
function clearApprovals(){const item=activeItem();if(item)item.reviewed={}}
function changeField(el){const field=el.dataset.field,scope=el.dataset.scope;const c=activeClient(),i=activeItem();let target=scope==='client'?c:scope==='item'?i:scope==='address'?i?.letterAddresses:scope==='sent'?i?.sentDates:null;if(!target)return;const key=scope==='address'?field:field;let val=el.type==='checkbox'?el.checked:el.value;if(scope==='item'&&field==='account'&&typeof val==='string'){const digits=(val.match(/\d/g)||[]);if(digits.length>4){val=digits.slice(-4).join('');el.value=val;toast('Only the last four digits are kept.')}}target[key]=val;if(scope==='client'&&(field==='name'||field==='isClient'))signature=null;if(scope!=='sent'&&field!=='notes'&&field!=='email'&&field!=='phone')clearApprovals();persist();}
function toggleArray(field,value,checked){const i=activeItem();if(!i)return;const a=new Set(arr(i[field]));if(checked)a.add(value);else a.delete(value);i[field]=[...a];clearApprovals();persist();render();}
function copyText(t){if(navigator.clipboard?.writeText)return navigator.clipboard.writeText(t).then(()=>toast('Copied to clipboard')).catch(()=>fallbackCopy(t));return fallbackCopy(t)}
function fallbackCopy(t){const area=document.createElement('textarea');area.value=t;area.style.position='fixed';area.style.opacity=0;document.body.appendChild(area);area.select();try{document.execCommand('copy');toast('Copied')}catch(_){toast('Unable to copy; select the text manually')}area.remove();}
function cleanCaseForCode(c){const x=structuredClone(c);for(const i of x.items){i.files=[];i.reviewed={};}return x;}
function encodeCode(c){return btoa(unescape(encodeURIComponent(JSON.stringify({version:1,case:cleanCaseForCode(c)}))))}
function decodeCode(s){if(s.length>2500000)throw Error('Case code too large');const obj=JSON.parse(decodeURIComponent(escape(atob(s.replace(/\s+/g,'')))));if(obj.version!==1||!obj.case||!Array.isArray(obj.case.items))throw Error('Invalid case code');const c=obj.case;c.id=ID();c.items=c.items.map(x=>({...newItem(),...x,id:ID(),files:[],reviewed:{},sentDates:x.sentDates||{}}));c.activeItemId=c.items[0]?.id;return c}
async function setSave(enabled){if(enabled){state.saving=true;persist();for(const [id,blob] of tempFiles)try{await idbPut({id,blob})}catch(_){toast('Some files could not be stored on this device.')}tempFiles.clear();toast('Device saving on • unencrypted');}else{if(!confirm('Turn off saving and permanently delete the saved local copy, including stored screenshots? Your current form will remain until a refresh.'))return;state.saving=false;localStorage.removeItem(STORE);await idbClear();tempFiles.clear();for(const c of state.clients)for(const i of c.items)i.files=[];toast('Local saving off; stored files cleared');}closeModal();render();}
function openDB(){return new Promise((resolve,reject)=>{if(!('indexedDB' in window))return reject(Error('IndexedDB unavailable'));const request=indexedDB.open(dbName,1);request.onupgradeneeded=()=>{request.result.createObjectStore('evidence',{keyPath:'id'})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
async function idbGet(id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('evidence','readonly'),r=tx.objectStore('evidence').get(id);r.onsuccess=()=>{db.close();resolve(r.result?.blob||null)};r.onerror=()=>{db.close();reject(r.error)}})}
async function idbPut(x){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('evidence','readwrite');tx.objectStore('evidence').put(x);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function idbDelete(id){const db=await openDB();return new Promise((resolve,reject)=>{const tx=db.transaction('evidence','readwrite');tx.objectStore('evidence').delete(id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>{db.close();reject(tx.error)}})}
async function idbClear(){try{const db=await openDB();await new Promise((resolve,reject)=>{const tx=db.transaction('evidence','readwrite');tx.objectStore('evidence').clear();tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});db.close()}catch(_){}}
async function getBlob(id){return tempFiles.get(id)||await idbGet(id)}
async function addEvidence(files){const i=activeItem();if(!i)return;let added=0;for(const file of Array.from(files)){if(!file.type.startsWith('image/')&&file.type!=='application/pdf'){toast('Only screenshots, images and PDFs are accepted');continue}const id=ID();try{if(state.saving)await idbPut({id,blob:file});else tempFiles.set(id,file);i.files.push({id,name:file.name||'Screenshot',type:file.type,size:file.size,createdAt:new Date().toISOString()});added++}catch(e){toast('Storage unavailable. Try fewer or smaller files.');break}}persist();render();toast(`${added} file${added===1?'':'s'} attached`)}
async function loadThumbs(){const i=activeItem();if(!i)return;for(const meta of i.files){if(!meta.type?.startsWith('image/'))continue;const el=document.getElementById('thumb-'+meta.id);if(!el)continue;try{let url=objectURLs.get(meta.id);if(!url){const file=await getBlob(meta.id);if(!file)continue;url=URL.createObjectURL(file);objectURLs.set(meta.id,url);}const img=document.createElement('img');img.src=url;img.className='doc-preview';img.alt='Screenshot thumbnail';el.replaceWith(img)}catch(_){}}}
async function viewFile(id){const i=activeItem(),meta=i?.files?.find(x=>x.id===id);if(!meta)return;const blob=await getBlob(id);if(!blob){toast('File unavailable. Restore it from a full backup.');return}const url=objectURLs.get(id)||URL.createObjectURL(blob);objectURLs.set(id,url);if(meta.type.startsWith('image/'))openModal(`<div class="modal-head"><h2>${E(meta.name)}</h2><button class="icon-btn" data-action="close-modal">×</button></div><img src="${url}" alt="Case evidence" style="width:100%;height:auto;max-height:65vh;object-fit:contain;background:#071020;border-radius:12px"><p class="small-print">Keep the original file stored securely. This app only displays the local copy.</p><a class="btn secondary" href="${url}" download="${E(meta.name)}">Save original</a>`);else{const a=document.createElement('a');a.href=url;a.download=meta.name;a.click();toast('Opened PDF download');}}
function bytesToBase64(bytes){let binary='';for(let k=0;k<bytes.length;k+=8192)binary+=String.fromCharCode(...bytes.subarray(k,k+8192));return btoa(binary)}
async function blobToDataURL(blob){const bytes=new Uint8Array(await blob.arrayBuffer());return `data:${blob.type||'application/octet-stream'};base64,${bytesToBase64(bytes)}`;}
function b64ToBlob(data){const [prefix,part]=data.split(',');const type=/data:([^;]+)/.exec(prefix)?.[1]||'application/octet-stream';const binary=atob(part);const b=new Uint8Array(binary.length);for(let x=0;x<binary.length;x++)b[x]=binary.charCodeAt(x);return new Blob([b],{type})}
async function makeBackup(includeFiles){const copy=structuredClone({clients:state.clients,activeId:state.activeId});const output={format:'dispute-studio-backup',version:1,exportedAt:new Date().toISOString(),...copy,evidence:{}};if(includeFiles){for(const c of state.clients)for(const i of c.items)for(const meta of arr(i.files)){try{const f=await getBlob(meta.id);if(f)output.evidence[meta.id]=await blobToDataURL(f)}catch(_){}}}else{for(const c of output.clients)for(const i of c.items)i.files=[];}for(const c of output.clients)for(const i of c.items)i.reviewed={};saveBlob(new Blob([JSON.stringify(output,null,2)],{type:'application/json'}),`dispute-studio-${includeFiles?'full':'cases'}-${TODAY()}.json`);toast('Backup downloaded — keep it private');}
async function importBackup(file){if(!confirm('Import this backup and REPLACE the current workspace? Export a backup of your current work first.'))return;try{const o=JSON.parse(await file.text());if(o.format!=='dispute-studio-backup'||o.version!==1||!Array.isArray(o.clients))throw Error('Incorrect file format');const clients=o.clients.map(c=>({...newClient(),...c,items:arr(c.items).map(i=>({...newItem(),...i,reviewed:{}}))}));await idbClear();tempFiles.clear();for(const [id,data] of Object.entries(o.evidence||{}))if(/^data:(image\/|application\/pdf)/.test(data))await idbPut({id,blob:b64ToBlob(data)});state.clients=clients;state.activeId=clients.some(c=>c.id===o.activeId)?o.activeId:clients[0]?.id||null;state.saving=true;state.tab='cases';persist();signature=null;closeModal();render();toast('Backup restored and saving enabled')}catch(e){toast('Import failed: '+e.message)}}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000)}
function pdfSafe(s){return String(s).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[\u2018\u2019]/g,"'").replace(/[\u2013\u2014]/g,'-').replace(/[\u201c\u201d]/g,'"').replace(/[^\x20-\x7E]/g,'?')}
function pdfEscape(s){return pdfSafe(s).replace(/\\/g,'\\\\').replace(/\(/g,'\\(').replace(/\)/g,'\\)')}
function wrapPdfLine(line,max=90){if(!line)return [''];const words=pdfSafe(line).split(/\s+/),out=[];let active='';for(const word of words){if((active+' '+word).trim().length>max&&active){out.push(active);active=word}else active=(active+' '+word).trim();while(active.length>max){out.push(active.slice(0,max));active=active.slice(max)}}if(active)out.push(active);return out.length?out:[''];}
function createPdf(l){const raw=l.text.split('\n'),pages=[[]];let y=741;function newline(){y-=15;if(y<70){pages.push([]);y=741}}for(const line of raw){if(line==='[[NEW_PAGE]]'){if(pages.at(-1).length){pages.push([]);y=741;}continue}if(line==='[[SIGNATURE]]'){if(signature){if(y<118){pages.push([]);y=741}pages.at(-1).push({type:'sig',y:y-47});y-=57;}else{y-=35;}continue}for(const text of wrapPdfLine(line)){pages.at(-1).push({type:'text',y,text});newline();}}
const encoder=new TextEncoder(),objects=[null],add=o=>(objects.push(o),objects.length-1);const catalog=add(''),pagesRoot=add('');const font=add('<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>');let imageId=null;if(signature){const data=Uint8Array.from(atob(signature.split(',')[1]),c=>c.charCodeAt(0));imageId=add({dict:`<< /Type /XObject /Subtype /Image /Width ${signatureDims.width} /Height ${signatureDims.height} /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length ${data.length} >>`,data});}
const pageIds=[];for(const entries of pages){const content=entries.map(ent=>ent.type==='sig'?'q 180 0 0 44 50 '+ent.y+' cm /Im1 Do Q':`BT /F1 10 Tf 1 0 0 1 50 ${ent.y} Tm (${pdfEscape(ent.text)}) Tj ET`).join('\n');const data=encoder.encode(content);const contents=add({dict:`<< /Length ${data.length} >>`,data});const id=add(`<< /Type /Page /Parent ${pagesRoot} 0 R /MediaBox [0 0 612 792] /Resources << /Font << /F1 ${font} 0 R >> ${imageId?`/XObject << /Im1 ${imageId} 0 R >>`:''} >> /Contents ${contents} 0 R >>`);pageIds.push(id)}objects[catalog]=`<< /Type /Catalog /Pages ${pagesRoot} 0 R >>`;objects[pagesRoot]=`<< /Type /Pages /Kids [${pageIds.map(x=>x+' 0 R').join(' ')}] /Count ${pageIds.length} >>`;
const chunks=[],offsets=[0];let size=0;const put=x=>{const data=typeof x==='string'?encoder.encode(x):x;chunks.push(data);size+=data.length};put('%PDF-1.4\n%Studio\n');for(let n=1;n<objects.length;n++){offsets[n]=size;const obj=objects[n];put(`${n} 0 obj\n`);if(typeof obj==='string')put(obj+'\n');else{put(obj.dict+'\nstream\n');put(obj.data);put('\nendstream\n')}put('endobj\n')};const start=size;put(`xref\n0 ${objects.length}\n0000000000 65535 f \n`);for(let n=1;n<objects.length;n++)put(String(offsets[n]).padStart(10,'0')+' 00000 n \n');put(`trailer\n<< /Size ${objects.length} /Root ${catalog} 0 R >>\nstartxref\n${start}\n%%EOF`);return new Blob(chunks,{type:'application/pdf'});}
function currentReady(){const i=activeItem(),c=activeClient();if(!i||!c)return false;const l=buildLetter(c,i);return !l.errors.length&&!!i.reviewed?.[letterKey()]}
async function exportPdf(){if(!currentReady()){toast('Confirm every statement and fill missing fields first');return}const l=buildLetter(activeClient(),activeItem());const pdf=createPdf(l);const name=`${clientLabel(activeClient())}-${state.letter}-${state.letter==='bureau'?state.bureau+'-':''}${TODAY()}.pdf`.replace(/[^a-zA-Z0-9_.-]/g,'-');try{const file=new File([pdf],name,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:l.label});return}}catch(e){if(e.name==='AbortError')return}saveBlob(pdf,name);toast('PDF saved — check your Downloads / Files');}
async function exportPacket(){const c=activeClient(),i=activeItem();const ready=packetList(c,i).filter(l=>l.ready);if(!ready.length){toast('Review at least one complete letter first');return}const pdf=createPdf({text:ready.map(l=>l.text).join('\n[[NEW_PAGE]]\n')});const fileName=`${clientLabel(c)}-dispute-packet-${TODAY()}.pdf`.replace(/[^a-zA-Z0-9_.-]/g,'-');try{const file=new File([pdf],fileName,{type:'application/pdf'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Dispute packet'});return}}catch(e){if(e.name==='AbortError')return}saveBlob(pdf,fileName);toast('Ready-letter packet saved');}
function printLetter(){if(!currentReady()){toast('Complete and confirm the letter first');return}const l=buildLetter(activeClient(),activeItem());const h=previewHtml(l);document.getElementById('printArea').innerHTML=`<div class="print-content">${h}</div>`;window.print();}
function readAloud(){if(!('speechSynthesis' in window)){toast('Speech is not supported in this browser');return}if(window.speechSynthesis.speaking){window.speechSynthesis.cancel();toast('Reading stopped');return}const all=document.querySelector('main')?.innerText||'';const u=new SpeechSynthesisUtterance(all.slice(0,12000));u.rate=.92;window.speechSynthesis.speak(u);toast('Reading aloud • tap again to stop');}
async function handleClick(event){const btn=event.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,val=btn.dataset.value,id=btn.dataset.id;if(action.startsWith('reader-')||action.startsWith('fk-')){await readerClick(action,val,btn);return;}switch(action){
case 'nav':go(val);break;
case 'advanced-with-item':fusionEnter(true);break;
case 'advanced-open-blank':fusionEnter(false);break;
case 'demo':{const c=demoClient();state.clients.push(c);state.activeId=c.id;state.step='account';signature=null;persist();go('cases');toast('Sample case loaded — fictional information');break}
case 'add-client':newClientModal();break;
case 'create-client':{const c=newClient(document.getElementById('newClientName')?.value.trim()||'');c.isClient=!!document.getElementById('newIsClient')?.checked;state.clients.push(c);state.activeId=c.id;state.step='profile';signature=null;persist();closeModal();go('cases');toast('New profile created');break}
case 'case-step':state.step=val;render();break;
case 'select-item':{const c=activeClient();if(c){c.activeItemId=id;signature=null;persist();render()}break}
case 'add-item':{const c=activeClient();if(c){const i=newItem();c.items.push(i);c.activeItemId=i.id;state.step='account';signature=null;persist();render();toast('New credit item created')}break}
case 'ownership':{const i=activeItem();if(i){i.ownership=val;clearApprovals();persist();render()}break}
case 'bureau-toggle':{const i=activeItem();if(i)toggleArray('bureaus',val,!i.bureaus.includes(val));break}
case 'letter-type':state.letter=val;render();break;
case 'open-packet-letter':state.letter=btn.dataset.type;state.bureau=btn.dataset.bureau||'Experian';render();window.scrollTo({top:0,behavior:'instant'});break;
case 'pdf-packet':await exportPacket();break;
case 'copy-packet':{const c=activeClient(),i=activeItem();const texts=packetList(c,i).filter(l=>l.ready).map(l=>l.text.replace('[[SIGNATURE]]',''));if(texts.length)copyText(texts.join('\n\n---- NEXT LETTER ----\n\n'));break}
case 'bureau-select':state.bureau=val;render();break;
case 'choose-files':document.getElementById('filePicker')?.click();break;
case 'signature':if(currentReady())signatureModal();else toast('Review the letter and fill required fields first');break;
case 'save-signature':{const canvas=document.getElementById('signaturePad');if(canvas){if(!signedStrokes){toast('Draw a signature first');break}signature=canvas.toDataURL('image/jpeg',.92);signatureDims={width:canvas.width,height:canvas.height};closeModal();render();toast('Signature added for this session')}break}
case 'clear-signature':{const canvas=document.getElementById('signaturePad');if(canvas){const ctx=canvas.getContext('2d');ctx.save();ctx.setTransform(1,0,0,1,0,0);ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.restore();signedStrokes=0;}break}
case 'copy-letter':if(currentReady()){const l=buildLetter(activeClient(),activeItem());copyText(l.text.replace('[[SIGNATURE]]','\n'));}else toast('Fill and review letter before copying');break;
case 'pdf-letter':await exportPdf();break;
case 'print-letter':printLetter();break;
case 'mark-sent':{if(!currentReady()){toast('Finalize letter before recording receipt');break}if(!confirm('Confirm the recipient actually received this correspondence TODAY? Do not mark a draft as submitted.'))break;const i=activeItem();const key=state.letter==='bureau'?state.bureau:state.letter==='collector'?'Collector':state.letter==='direct'?'Creditor':state.letter+'-'+state.bureau;i.sentDates[key]=TODAY();persist();render();toast('Receipt date recorded');break}
case 'settings':openModal(settingsModal());break;
case 'close-modal':closeModal();break;
case 'toggle-save':await setSave(!state.saving);break;
case 'backup-data':await makeBackup(false);break;
case 'backup-full':await makeBackup(true);break;
case 'copy-code':{const c=activeClient();if(c)await copyText(encodeCode(c));break}
case 'load-code':{const v=document.getElementById('caseCodeInput')?.value||'';if(!v.trim()){toast('Paste a code first');break}try{const c=decodeCode(v);state.clients.push(c);state.activeId=c.id;state.tab='cases';signature=null;persist();closeModal();render();toast('Case imported — verify all information')}catch(_){toast('Could not load this case code')}}break;
case 'clear-all':{if(!confirm('DELETE ALL CASES, NOTES AND SAVED EVIDENCE ON THIS DEVICE? This cannot be reversed.'))break;localStorage.removeItem(STORE);FK.clearAll();await idbClear();tempFiles.clear();for(const url of objectURLs.values())URL.revokeObjectURL(url);objectURLs.clear();state=initialState();signature=null;closeModal();render();toast('Workspace erased');break}
case 'delete-client':{const c=activeClient();if(!c)break;if(!confirm(`Delete the ENTIRE profile for ${clientLabel(c)}, all its items and evidence?`))break;for(const i of c.items)for(const meta of arr(i.files)){tempFiles.delete(meta.id);await idbDelete(meta.id).catch(()=>{});}state.clients=state.clients.filter(x=>x.id!==c.id);state.activeId=state.clients[0]?.id||null;signature=null;persist();closeModal();render();toast('Profile deleted');break}
case 'delete-item':{const c=activeClient(),i=activeItem();if(!c||!i)break;if(!confirm('Delete this credit item and all its attached screenshots?'))break;for(const meta of arr(i.files)){tempFiles.delete(meta.id);await idbDelete(meta.id).catch(()=>{});}c.items=c.items.filter(x=>x.id!==i.id);if(!c.items.length)c.items.push(newItem());c.activeItemId=c.items[0].id;signature=null;persist();render();toast('Item deleted');break}
case 'remove-file':{const i=activeItem();if(!i)return;if(!confirm('Delete this attached evidence file?'))break;i.files=i.files.filter(x=>x.id!==id);tempFiles.delete(id);await idbDelete(id).catch(()=>{});const url=objectURLs.get(id);if(url)URL.revokeObjectURL(url);objectURLs.delete(id);persist();render();toast('Attachment removed');break}
case 'open-file':await viewFile(id);break;
case 'speak-help':readAloud();break;
}}
function handleInput(event){const el=event.target;
if(el.dataset.bureauExplain){const i=activeItem(),b=el.dataset.bureauExplain;if(i&&BUREAUS.includes(b)){i.bureauDisputes??={};i.bureauDisputes[b]??={issues:[],why:'',correctBalance:''};i.bureauDisputes[b].why=el.value;clearApprovals();persist();const preview=document.getElementById('letterPreview');if(preview)preview.innerHTML=previewHtml(buildLetter(activeClient(),i));}return;}
if(el.dataset.responseBureau){const item=activeItem(),b=el.dataset.responseBureau;if(item&&BUREAUS.includes(b)){item.responses??={};item.responses[b]??={};item.responses[b][el.dataset.responseKey]=el.value;persist()}return}if(readerInput(el))return;if(el.dataset.field!==undefined&&el.dataset.scope){changeField(el);if(state.tab==='letters'){const l=buildLetter(activeClient(),activeItem());const p=document.getElementById('letterPreview');if(p)p.innerHTML=previewHtml(l);}return;}}
function handleChange(event){const el=event.target;if(readerChange(el))return;
if(el.dataset.bureauIssue){const i=activeItem(),b=el.dataset.bureauIssue;if(i&&BUREAUS.includes(b)){i.bureauDisputes??={};i.bureauDisputes[b]??={issues:[],why:'',correctBalance:''};const d=i.bureauDisputes[b],issue=el.dataset.bureauIssueKey;d.issues=el.checked?[...new Set([...(d.issues||[]),issue])]:(d.issues||[]).filter(x=>x!==issue);clearApprovals();persist();render()}return;}
if(el.dataset.bureauCorrect){const i=activeItem(),b=el.dataset.bureauCorrect;if(i&&BUREAUS.includes(b)){i.bureauDisputes??={};i.bureauDisputes[b]??={issues:[],why:'',correctBalance:''};i.bureauDisputes[b].correctBalance=el.value;clearApprovals();persist();render()}return;}

 if(el.dataset.responseBureau){const item=activeItem(),b=el.dataset.responseBureau,k=el.dataset.responseKey;if(item&&BUREAUS.includes(b)&&['date','status','note'].includes(k)){item.responses??={};item.responses[b]??={};item.responses[b][k]=el.value;persist();}return;}if(el.id==='filePicker'){addEvidence(el.files);el.value='';return}if(el.id==='backupImporter'){const f=el.files?.[0];if(f)importBackup(f);return}if(el.dataset.array){toggleArray(el.dataset.array,el.dataset.value,el.checked);return}if(el.dataset.action==='select-client'){state.activeId=el.value;state.step='profile';signature=null;render();persist();return}if(el.dataset.dateKey){const i=activeItem();if(i){i.sentDates[el.dataset.dateKey]=el.value;persist();render()}return}if(el.dataset.reviewed!==undefined){const i=activeItem();if(i){i.reviewed[el.dataset.reviewed]=el.checked;persist();render()}return}if(el.dataset.field!==undefined){changeField(el);render();return}}
let signatureDims={width:900,height:220};
function installHandlers(){document.addEventListener('click',handleClick);document.addEventListener('input',handleInput);document.addEventListener('change',handleChange);const dz=()=>document.getElementById('dropzone');document.addEventListener('dragover',e=>{if(dz()&&dz().contains(e.target)){e.preventDefault();dz().style.borderColor='#62e4c8'}});document.addEventListener('dragleave',e=>{if(dz()&&dz().contains(e.target))dz().style.borderColor=''});document.addEventListener('drop',e=>{if(dz()&&dz().contains(e.target)){e.preventDefault();dz().style.borderColor='';addEvidence(e.dataTransfer.files)}});document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});}
installHandlers();if(location.hash==='#reader')state.tab='reader';render();fusionFromAdvanced();if('serviceWorker' in navigator&&location.protocol==='https:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(()=>{}));
